    readonly OpacitySlider capsuleOpacity=new OpacitySlider();readonly Label capsuleOpacityValue=new Label();bool petOpacityDirty;
    Control BuildPetAppearance(){
        var box=new Surface{Dock=DockStyle.Fill,Padding=new Padding(16,12,16,12),BackColor=Color.FromArgb(19,25,30)};
        var rows=new BufferedTable{Dock=DockStyle.Fill,ColumnCount=1,RowCount=6,Margin=Padding.Empty};foreach(int h in new[]{26,42,48,22,34,24})rows.RowStyles.Add(new RowStyle(SizeType.Absolute,h));box.Controls.Add(rows);rows.Controls.Add(Caption("胶囊与圆环",10,Ink),0,0);
        var actions=new BufferedTable{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1,Margin=Padding.Empty};actions.RowStyles.Add(new RowStyle(SizeType.Percent,100));actions.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));actions.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));
        var all=new ActionButton{Text="统一配色",Dock=DockStyle.Fill,Margin=new Padding(0,0,10,8)};all.Click+=delegate{PickPetColor(PetColorTarget.All);};actions.Controls.Add(all,0,0);
        var reset=new ActionButton{Text="恢复默认",Dock=DockStyle.Fill,Margin=new Padding(0,0,0,8)};reset.Click+=delegate{if(pets==null)return;pets.Preferences.HubColor=pets.Preferences.CapsuleColor=pets.Preferences.RingColor="#4E8FE4";pets.Preferences.CapsuleOpacity=94;SavePetAppearance();};actions.Controls.Add(reset,1,0);rows.Controls.Add(actions,0,1);
        var colors=new BufferedTable{Dock=DockStyle.Fill,ColumnCount=3,RowCount=1,Margin=Padding.Empty};colors.RowStyles.Add(new RowStyle(SizeType.Percent,100));foreach(var button in new[]{hubColorButton,capsuleColorButton,ringColorButton}){colors.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100F/3));button.Dock=DockStyle.Fill;button.Margin=new Padding(0,0,10,12);}ringColorButton.Margin=new Padding(0,0,0,12);
        hubColorButton.Text="左侧按钮";capsuleColorButton.Text="中间胶囊";ringColorButton.Text="右侧圆环";colors.Controls.Add(hubColorButton,0,0);colors.Controls.Add(capsuleColorButton,1,0);colors.Controls.Add(ringColorButton,2,0);
        hubColorButton.Click+=delegate{PickPetColor(PetColorTarget.Hub);};capsuleColorButton.Click+=delegate{PickPetColor(PetColorTarget.Capsule);};ringColorButton.Click+=delegate{PickPetColor(PetColorTarget.Ring);};rows.Controls.Add(colors,0,2);
        var opacityHeading=new BufferedTable{Dock=DockStyle.Fill,ColumnCount=2,RowCount=1,Margin=Padding.Empty};opacityHeading.RowStyles.Add(new RowStyle(SizeType.Percent,100));opacityHeading.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));opacityHeading.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,52));opacityHeading.Controls.Add(Caption("胶囊与圆环不透明度",9,Muted),0,0);
        capsuleOpacity.Minimum=0;capsuleOpacity.Maximum=100;capsuleOpacity.Value=94;capsuleOpacity.Dock=DockStyle.Fill;capsuleOpacity.Margin=Padding.Empty;capsuleOpacity.BackColor=box.BackColor;capsuleOpacity.AccessibleName="胶囊与圆环不透明度";
        capsuleOpacity.ValueChanged+=delegate{capsuleOpacityValue.Text=capsuleOpacity.Value+"%";if(petSync||pets==null)return;pets.Preferences.CapsuleOpacity=capsuleOpacity.Value;petOpacityDirty=true;if(pets.Window!=null)pets.Window.AdvanceOnce();};
        capsuleOpacity.MouseUp+=delegate{CommitPetOpacity();};capsuleOpacity.KeyUp+=delegate{CommitPetOpacity();};capsuleOpacity.Leave+=delegate{CommitPetOpacity();};rows.Controls.Add(capsuleOpacity,0,4);
        capsuleOpacityValue.Dock=DockStyle.Fill;capsuleOpacityValue.ForeColor=Ink;capsuleOpacityValue.TextAlign=ContentAlignment.MiddleRight;opacityHeading.Controls.Add(capsuleOpacityValue,1,0);rows.Controls.Add(opacityHeading,0,3);
        rows.Controls.Add(new Label{Dock=DockStyle.Fill,Text="同时控制两侧圆环与胶囊底色；图标和文字保持清晰。",ForeColor=Muted,Font=new Font(Font.FontFamily,8F),AutoEllipsis=true},0,5);return box;
    }
    void PickPetColor(PetColorTarget target){if(pets==null)return;string current=target==PetColorTarget.Hub?pets.Preferences.HubColor:target==PetColorTarget.Ring?pets.Preferences.RingColor:pets.Preferences.CapsuleColor;string label=target==PetColorTarget.All?"统一配色":target==PetColorTarget.Hub?"左侧按钮配色":target==PetColorTarget.Capsule?"中间胶囊配色":"右侧圆环配色";using(var dialog=new HubColorPicker(ColorTranslator.FromHtml(PetPreferences.NormalizeColor(current)),label)){if(dialog.ShowDialog(this)!=DialogResult.OK)return;ApplyPetColor(target,HubColorMath.Hex(dialog.SelectedColor));}}
    void ApplyPetColor(PetColorTarget target,string color){if(pets==null)return;color=PetPreferences.NormalizeColor(color);if(target==PetColorTarget.All||target==PetColorTarget.Hub)pets.Preferences.HubColor=color;if(target==PetColorTarget.All||target==PetColorTarget.Capsule)pets.Preferences.CapsuleColor=color;if(target==PetColorTarget.All||target==PetColorTarget.Ring)pets.Preferences.RingColor=color;SavePetAppearance();}
    void CommitPetOpacity(){if(petOpacityDirty&&pets!=null)SavePetAppearance();}
    void SavePetAppearance(){pets.Preferences.Save(stateDirectory);petOpacityDirty=false;SyncPetAppearance();if(pets.Window!=null)pets.Window.AdvanceOnce();}
    void SyncPetAppearance(){if(pets==null)return;bool previous=petSync;petSync=true;try{hubColorButton.Swatch=ColorTranslator.FromHtml(PetPreferences.NormalizeColor(pets.Preferences.HubColor));capsuleColorButton.Swatch=ColorTranslator.FromHtml(PetPreferences.NormalizeColor(pets.Preferences.CapsuleColor));ringColorButton.Swatch=ColorTranslator.FromHtml(PetPreferences.NormalizeColor(pets.Preferences.RingColor));hubColorButton.Invalidate();capsuleColorButton.Invalidate();ringColorButton.Invalidate();capsuleOpacity.Value=Math.Max(0,Math.Min(100,pets.Preferences.CapsuleOpacity));capsuleOpacityValue.Text=capsuleOpacity.Value+"%";}finally{petSync=previous;}}
}

// Native WinForms color tools; no system ColorDialog or external UI runtime.
internal static class HubColorMath {
    public static Color FromHsv(double hue,double saturation,double value){
        hue=((hue%360)+360)%360;saturation=Math.Max(0,Math.Min(1,saturation));value=Math.Max(0,Math.Min(1,value));
        double c=value*saturation,x=c*(1-Math.Abs((hue/60)%2-1)),m=value-c,r=0,g=0,b=0;
        if(hue<60){r=c;g=x;}else if(hue<120){r=x;g=c;}else if(hue<180){g=c;b=x;}else if(hue<240){g=x;b=c;}else if(hue<300){r=x;b=c;}else{r=c;b=x;}
        return Color.FromArgb((int)Math.Round((r+m)*255),(int)Math.Round((g+m)*255),(int)Math.Round((b+m)*255));
    }
    public static void ToHsv(Color color,out double hue,out double saturation,out double value){
        double r=color.R/255D,g=color.G/255D,b=color.B/255D,max=Math.Max(r,Math.Max(g,b)),min=Math.Min(r,Math.Min(g,b)),delta=max-min;
        value=max;saturation=max==0?0:delta/max;hue=delta==0?0:max==r?60*((g-b)/delta%6):max==g?60*((b-r)/delta+2):60*((r-g)/delta+4);if(hue<0)hue+=360;
    }
    public static string Hex(Color color){return "#"+color.R.ToString("X2")+color.G.ToString("X2")+color.B.ToString("X2");}
}
internal sealed class HubSaturationPlane : Control {
    Bitmap bitmap;double hue,saturation,value=1;public event EventHandler ColorChanged;
    public double Hue{get{return hue;}}public double Saturation{get{return saturation;}}public double Value{get{return value;}}
    float Unit{get{return Math.Max(.8F,Font.Height/18F);}}
    RectangleF ColorBox{get{float p=6*Unit;return new RectangleF(p,p,Math.Max(1,Width-2*p),Math.Max(1,Height-2*p));}}
    public HubSaturationPlane(){SetStyle(ControlStyles.AllPaintingInWmPaint|ControlStyles.UserPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);TabStop=true;Cursor=Cursors.Cross;AccessibleName="饱和度与明度选色平面";}
    public void SetState(double h,double s,double v){bool changed=Math.Abs(hue-h)>.001;hue=((h%360)+360)%360;saturation=Math.Max(0,Math.Min(1,s));value=Math.Max(0,Math.Min(1,v));if(changed)ClearBitmap();Invalidate();}
    void ClearBitmap(){if(bitmap!=null){bitmap.Dispose();bitmap=null;}}
    protected override void OnSizeChanged(EventArgs e){ClearBitmap();base.OnSizeChanged(e);}
    protected override void OnFontChanged(EventArgs e){ClearBitmap();base.OnFontChanged(e);}
    protected override void Dispose(bool disposing){if(disposing)ClearBitmap();base.Dispose(disposing);}
    void Choose(Point point){var box=ColorBox;saturation=Math.Max(0,Math.Min(1,(point.X-box.Left)/Math.Max(1,box.Width-1)));value=1-Math.Max(0,Math.Min(1,(point.Y-box.Top)/Math.Max(1,box.Height-1)));Invalidate();if(ColorChanged!=null)ColorChanged(this,EventArgs.Empty);}
    protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);if(e.Button!=MouseButtons.Left)return;Focus();Capture=true;Choose(e.Location);}
    protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);if(Capture&&(e.Button&MouseButtons.Left)!=0)Choose(e.Location);}
    protected override void OnMouseUp(MouseEventArgs e){base.OnMouseUp(e);if(e.Button==MouseButtons.Left)Capture=false;}
    protected override bool IsInputKey(Keys keyData){Keys key=keyData&Keys.KeyCode;return key==Keys.Left||key==Keys.Right||key==Keys.Up||key==Keys.Down||base.IsInputKey(keyData);}
    protected override void OnKeyDown(KeyEventArgs e){double step=e.Shift ? .05 : .01;if(e.KeyCode==Keys.Left)saturation=Math.Max(0,saturation-step);else if(e.KeyCode==Keys.Right)saturation=Math.Min(1,saturation+step);else if(e.KeyCode==Keys.Up)value=Math.Min(1,value+step);else if(e.KeyCode==Keys.Down)value=Math.Max(0,value-step);else{base.OnKeyDown(e);return;}e.Handled=true;Invalidate();if(ColorChanged!=null)ColorChanged(this,EventArgs.Empty);base.OnKeyDown(e);}
    protected override void OnGotFocus(EventArgs e){base.OnGotFocus(e);Invalidate();}protected override void OnLostFocus(EventArgs e){base.OnLostFocus(e);Invalidate();}
    protected override void OnPaint(PaintEventArgs e){
        base.OnPaint(e);var box=ColorBox;var g=e.Graphics;g.SmoothingMode=System.Drawing.Drawing2D.SmoothingMode.AntiAlias;
        if(bitmap==null&&Width>0&&Height>0){bitmap=new Bitmap(Width,Height,System.Drawing.Imaging.PixelFormat.Format32bppPArgb);using(var bg=Graphics.FromImage(bitmap))using(var horizontal=new System.Drawing.Drawing2D.LinearGradientBrush(new PointF(box.Left,0),new PointF(box.Right,0),Color.White,HubColorMath.FromHsv(hue,1,1)))using(var vertical=new System.Drawing.Drawing2D.LinearGradientBrush(new PointF(0,box.Top),new PointF(0,box.Bottom),Color.FromArgb(0,0,0,0),Color.Black)){bg.FillRectangle(horizontal,box);bg.FillRectangle(vertical,box);}}
        using(var shape=IconAssets.Round(box,11*Unit)){var state=g.Save();g.SetClip(shape);if(bitmap!=null)g.DrawImageUnscaled(bitmap,0,0);g.Restore(state);using(var border=new Pen(Focused?Color.FromArgb(143,188,247):Color.FromArgb(52,63,77),Focused?1.5F*Unit:Unit))g.DrawPath(border,shape);}
        float x=box.Left+(float)saturation*(box.Width-1),y=box.Top+(float)(1-value)*(box.Height-1),radius=5*Unit;
        using(var dark=new Pen(Color.FromArgb(180,4,9,16),4*Unit))using(var light=new Pen(Color.White,2*Unit)){g.DrawEllipse(dark,x-radius,y-radius,radius*2,radius*2);g.DrawEllipse(light,x-radius,y-radius,radius*2,radius*2);}
    }
}
